import{_ as t,o as s,c as o,a3 as i}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Désactiver la correction du style des icônes","description":"Découvrez comment désactiver la correction du style des icônes et quand utiliser cette option de performance.","frontmatter":{"title":"Désactiver la correction du style des icônes","description":"Découvrez comment désactiver la correction du style des icônes et quand utiliser cette option de performance."},"headers":[],"relativePath":"fr/projects/uix/extras/disable-icon-styling.md","filePath":"fr/projects/uix/extras/disable-icon-styling.md","lastUpdated":1793113714000}'),r={name:"fr/projects/uix/extras/disable-icon-styling.md"};function a(n,e,c,l,d,u){return s(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="desactiver-la-correction-du-style-des-icones" tabindex="-1">Désactiver la correction du style des icônes <a class="header-anchor" href="#desactiver-la-correction-du-style-des-icones" aria-label="Permalink to &quot;Désactiver la correction du style des icônes&quot;">​</a></h1><p>Par défaut, UIX corrige les éléments d&#39;icône standard de Home Assistant (<code>ha-icon</code>, <code>ha-state-icon</code>, <code>ha-svg-icon</code>) pour permettre les styles et surcharges personnalisés, comme <code>--uix-icon</code>, <code>--uix-icon-color</code>, <code>--uix-icon-dim</code> ou <code>--uix-icon-for-&lt;entity_id&gt;</code>. UIX propose une option pour désactiver cette correction afin d&#39;améliorer le rendu et de réduire la charge processeur des appareils peu puissants.</p><h2 id="reglage-depuis-l-interface-de-l-integration" tabindex="-1">Réglage depuis l&#39;interface de l&#39;intégration <a class="header-anchor" href="#reglage-depuis-l-interface-de-l-integration" aria-label="Permalink to &quot;Réglage depuis l&#39;interface de l&#39;intégration&quot;">​</a></h2><p>Cette option est <strong>désactivée par défaut</strong>. Pour l&#39;activer :</p><ol><li>Dans Home Assistant, ouvrez <strong>Paramètres → Appareils et services → UI eXtension → Configurer</strong>.</li><li>Sélectionnez <strong>Réglages de performance</strong>.</li><li>Activez <strong>Désactiver la correction du style des icônes</strong>.</li><li>Enregistrez.</li></ol><p>Le réglage prend effet immédiatement dans toutes les sessions de navigateur connectées ; aucun rechargement n&#39;est nécessaire.</p><h2 id="comportement-lorsqu-elle-est-activee" tabindex="-1">Comportement lorsqu&#39;elle est activée <a class="header-anchor" href="#comportement-lorsqu-elle-est-activee" aria-label="Permalink to &quot;Comportement lorsqu&#39;elle est activée&quot;">​</a></h2><p>Lorsque cette option est activée :</p><ul><li>Les éléments d&#39;icône standard Home Assistant ne sont <strong>pas corrigés</strong> ni surveillés pour les propriétés d&#39;icône personnalisées.</li><li>Les surcharges existantes d&#39;icône ou de couleur via des variables CSS, par exemple <code>--uix-icon</code>, <code>--uix-icon-color</code>, <code>--uix-icon-dim</code> ou <code>--uix-icon-for-*</code>, ne s&#39;appliquent <strong>pas</strong> aux éléments d&#39;icône standard.</li></ul>',9)])])}const g=t(r,[["render",a]]);export{m as __pageData,g as default};
